PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "is_admin" tinyint(1) not null default '0');
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "services" ("id" integer primary key autoincrement not null, "category" varchar not null, "name" varchar not null, "slug" varchar not null, "badge" varchar, "duration" varchar, "price_estimate" varchar, "description" text, "syllabus" text, "target_audience" text, "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'published');
CREATE TABLE IF NOT EXISTS "cities" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "island" varchar, "is_hub" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "lat" numeric, "lng" numeric, "address" varchar, "province" varchar, "sentra_praktik" varchar, "maps_embed_url" text, "bps_code" varchar, "classification" varchar, "status" varchar not null default 'published', "wilayah_code" varchar, "bps_province_code" varchar);
CREATE TABLE IF NOT EXISTS "city_service_contents" ("id" integer primary key autoincrement not null, "city_id" integer not null, "service_id" integer, "category" varchar, "seo_title" varchar, "meta_description" text, "custom_heading" varchar, "custom_content" text, "created_at" datetime, "updated_at" datetime, foreign key("city_id") references "cities"("id") on delete cascade, foreign key("service_id") references "services"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "kecamatans" ("id" integer primary key autoincrement not null, "city_id" integer not null, "name" varchar not null, "slug" varchar not null, "address" varchar, "lat" numeric, "lng" numeric, "google_maps_url" text, "seo_title" varchar, "meta_description" text, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, "bps_code" varchar, "wilayah_code" varchar, foreign key("city_id") references "cities"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "locations" ("id" integer primary key autoincrement not null, "city_id" integer not null, "kecamatan_id" integer, "location_name" varchar not null, "address" text, "lat" numeric, "lng" numeric, "google_maps_url" text, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("city_id") references "cities"("id") on delete cascade, foreign key("kecamatan_id") references "kecamatans"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "articles" ("id" integer primary key autoincrement not null, "category" varchar, "service_id" integer, "city_id" integer, "title" varchar not null, "slug" varchar not null, "excerpt" text not null, "content" text not null, "reading_time" integer not null default ('7'), "faq_items" text, "seo_title" varchar, "meta_description" text, "focus_keywords" varchar, "status" varchar not null default ('published'), "created_at" datetime, "updated_at" datetime, "kecamatan_id" integer, "internal_links" text, "image" varchar, "image_prompts" text, foreign key("city_id") references cities("id") on delete set null on update no action, foreign key("service_id") references services("id") on delete set null on update no action, foreign key("kecamatan_id") references "kecamatans"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "faqs" ("id" integer primary key autoincrement not null, "service_id" integer, "city_id" integer, "kecamatan_id" integer, "question" text not null, "answer" text not null, "order" integer not null default '0', "status" varchar not null default 'published', "created_at" datetime, "updated_at" datetime, foreign key("service_id") references "services"("id") on delete set null, foreign key("city_id") references "cities"("id") on delete set null, foreign key("kecamatan_id") references "kecamatans"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "training_schedules" ("id" integer primary key autoincrement not null, "service_id" integer not null, "city_id" integer not null, "date" date not null, "start_time" varchar default '08:30', "end_time" varchar default '16:30', "location" varchar not null, "available_slots" integer not null default '20', "status" varchar not null default 'open', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("service_id") references "services"("id") on delete cascade, foreign key("city_id") references "cities"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "tickets" ("id" integer primary key autoincrement not null, "ticket_number" varchar not null, "name" varchar not null, "company" varchar, "phone" varchar not null, "email" varchar, "category" varchar, "service_id" integer, "city_id" integer, "subject" varchar not null, "message" text not null, "status" varchar check ("status" in ('pending', 'in_progress', 'resolved', 'closed')) not null default 'pending', "priority" varchar check ("priority" in ('low', 'medium', 'high', 'urgent')) not null default 'medium', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("service_id") references "services"("id") on delete set null, foreign key("city_id") references "cities"("id") on delete set null);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "services_category_index" on "services" ("category");
CREATE UNIQUE INDEX "services_slug_unique" on "services" ("slug");
CREATE UNIQUE INDEX "cities_slug_unique" on "cities" ("slug");
CREATE UNIQUE INDEX "city_service_cat_unique" on "city_service_contents" ("city_id", "service_id", "category");
CREATE INDEX "kecamatans_city_id_index" on "kecamatans" ("city_id");
CREATE INDEX "kecamatans_slug_index" on "kecamatans" ("slug");
CREATE UNIQUE INDEX "kecamatans_city_id_slug_unique" on "kecamatans" ("city_id", "slug");
CREATE INDEX "locations_city_id_index" on "locations" ("city_id");
CREATE INDEX "locations_kecamatan_id_index" on "locations" ("kecamatan_id");
CREATE INDEX "articles_category_status_index" on "articles" ("category", "status");
CREATE INDEX "articles_city_id_status_index" on "articles" ("city_id", "status");
CREATE INDEX "articles_service_id_status_index" on "articles" ("service_id", "status");
CREATE UNIQUE INDEX "articles_slug_unique" on "articles" ("slug");
CREATE INDEX "articles_kecamatan_id_index" on "articles" ("kecamatan_id");
CREATE INDEX "faqs_service_id_index" on "faqs" ("service_id");
CREATE INDEX "faqs_city_id_index" on "faqs" ("city_id");
CREATE INDEX "faqs_kecamatan_id_index" on "faqs" ("kecamatan_id");
CREATE INDEX "faqs_status_index" on "faqs" ("status");
CREATE INDEX "training_schedules_service_id_index" on "training_schedules" ("service_id");
CREATE INDEX "training_schedules_city_id_index" on "training_schedules" ("city_id");
CREATE INDEX "training_schedules_date_index" on "training_schedules" ("date");
CREATE INDEX "training_schedules_status_index" on "training_schedules" ("status");
CREATE UNIQUE INDEX "cities_bps_code_unique" on "cities" ("bps_code");
CREATE UNIQUE INDEX "kecamatans_city_id_bps_code_unique" on "kecamatans" ("city_id", "bps_code");
CREATE UNIQUE INDEX "cities_wilayah_code_unique" on "cities" ("wilayah_code");
CREATE UNIQUE INDEX "kecamatans_city_id_wilayah_code_unique" on "kecamatans" ("city_id", "wilayah_code");
CREATE INDEX "tickets_status_index" on "tickets" ("status");
CREATE INDEX "tickets_ticket_number_index" on "tickets" ("ticket_number");
CREATE UNIQUE INDEX "tickets_ticket_number_unique" on "tickets" ("ticket_number");
CREATE UNIQUE INDEX "articles_service_category_city_kec_unique" on "articles" ("service_id", "category", "city_id", "kecamatan_id");
COMMIT;
